class Solution {
  public boolean[] findAnswer(int[] parent, String s) {
    int n = parent.length;
    int[] start = new int[n + 1];
    for (int i = 1; i < n; i++) start[parent[i] + 1]++;
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], kids = new int[n];
    for (int i = 1; i < n; i++) kids[start[parent[i]] + fill[parent[i]]++] = i;
    int[] L = new int[n], R = new int[n], ptr = new int[n], stack = new int[n];
    char[] order = new char[n];
    int sp = 0, counter = 0;
    stack[sp++] = 0;
    L[0] = 0;
    while (sp > 0) {
      int u = stack[sp - 1];
      if (start[u] + ptr[u] < start[u + 1]) {
        int v = kids[start[u] + ptr[u]++];
        L[v] = counter;
        stack[sp++] = v;
      } else {
        sp--;
        R[u] = counter;
        order[counter++] = s.charAt(u);
      }
    }
    int m = 2 * n + 1;
    char[] t = new char[m];
    for (int i = 0; i < n; i++) t[2 * i + 1] = order[i];
    int[] p = new int[m];
    for (int i = 0, l = 0, r = -1; i < m; i++) {
      int k = i > r ? 0 : Math.min(p[l + r - i], r - i);
      while (i - k - 1 >= 0 && i + k + 1 < m && t[i - k - 1] == t[i + k + 1]) k++;
      p[i] = k;
      if (i + k > r) {
        l = i - k;
        r = i + k;
      }
    }
    boolean[] ans = new boolean[n];
    for (int i = 0; i < n; i++) ans[i] = p[L[i] + R[i] + 1] >= R[i] - L[i] + 1;
    return ans;
  }
}
